  { x: -0.6, w: 0.98, y0: 0.14, ym: 0.68, y1: 0.86 }, { x: 0.5, w: 0.97, y0: 0.14, ym: 0.62, y1: 0.74 },
  { x: 1.5, w: 0.95, y0: 0.14, ym: 0.5, y1: 0.58 }, { x: 2.1, w: 0.86, y0: 0.16, ym: 0.37, y1: 0.43 }, { x: 2.27, w: 0.7, y0: 0.2, ym: 0.29, y1: 0.33 }
