350	    body: new THREE.InstancedMesh(box, MAT.vehicle, list.length),
351	    cabin: new THREE.InstancedMesh(box, MAT.glass, list.length),
352	    head: new THREE.InstancedMesh(box, MAT.headLamp, list.length),
353	    tail: new THREE.InstancedMesh(box, MAT.tailLamp, list.length)
354	  };
355	  const col = new THREE.Color();
356	  list.forEach((v, i) => T.body.setColorAt(i, col.setHex(v.color)));
357	  for (const mm of [T.body, T.cabin, T.head, T.tail]) { mm.frustumCulled = false; mm.instanceMatrix.setUsage(THREE.DynamicDrawUsage); bridge.life.add(mm); }
358	  T.body.castShadow = true;
359	  return T;
360	}
361	/* closable: có theo lệnh đóng cầu của thời tiết (bão) không; Hầm vượt sông Hàn truyền false (hầm vẫn lưu thông) */
362	const HIDDEN_M = new THREE.Matrix4().makeScale(0, 0, 0);
363	const _base = new THREE.Vector3();
364	/* Không cấp phát mỗi khung (D-018); đèn pha/hậu ẩn ban ngày nên không ghi ma trận đèn khi ẩn (vị trí xe vẫn cộng dồn) */
365	export function stepTraffic(T: Traffic, dt: number, profile: Profile, closable = true) {
366	  const range = T.x1 - T.x0, base = _base, lamps = shared.uNight.value > 0.3;
367	  T.head.visible = T.tail.visible = lamps;
368	  for (let i = 0; i < T.list.length; i++) {
369	    const v = T.list[i], ty = TYPES[v.type];
370	    v.s += v.dir * v.speed * dt; if (v.s > T.x1) v.s -= range; if (v.s < T.x0) v.s += range;
371	    if (closable && vanished(i, weatherFx.clear)) {   // đóng cầu (bão): dọn dần xe
372	      T.body.setMatrixAt(i, HIDDEN_M); T.cabin.setMatrixAt(i, HIDDEN_M); if (lamps) { T.head.setMatrixAt(i, HIDDEN_M); T.tail.setMatrixAt(i, HIDDEN_M); }
373	      continue;
374	    }
375	    const y = profile(v.s), slope = (profile(v.s + 1) - profile(v.s - 1)) / 2;
376	    _q.setFromEuler(_e.set(0, v.dir > 0 ? 0 : Math.PI, Math.atan(slope * v.dir), 'YZX'));
377	    base.set(v.s, y + 0.03, v.dir * v.lane);                 // tọa độ cục bộ của group cầu
378	    placePart(T.body, i, base, _q, 0, 0.3 + ty.h / 2, ty.len, ty.h, ty.w);
379	    placePart(T.cabin, i, base, _q, ty.co * ty.len, 0.3 + ty.h + ty.ch / 2, ty.cl, ty.ch, ty.cw);
380	    if (!lamps) continue;
381	    placePart(T.head, i, base, _q, ty.len / 2 + 0.04, 0.3 + ty.h * 0.6, 0.1, 0.22, ty.w * 0.8);
382	    placePart(T.tail, i, base, _q, -ty.len / 2 - 0.04, 0.3 + ty.h * 0.6, 0.1, 0.22, ty.w * 0.8);
383	  }
384	  T.body.instanceMatrix.needsUpdate = T.cabin.instanceMatrix.needsUpdate = true;
385	  if (lamps) T.head.instanceMatrix.needsUpdate = T.tail.instanceMatrix.needsUpdate = true;
386	}
387	import * as THREE from 'three';
388	import { CONFIG } from '../config';
389	import { scene } from '../core/renderer';
390	import { MAT } from '../core/materials';
391	import { windFx, weatherFx, vanished, shared } from '../core/shared';
392	import { rand } from '../common/math';
393	import type { BoatTypeId } from '../config';
394	import { btCreateFleet, btSetInfo, btSetBoat, btHideBoat, btCommit, btFleets, type BoatFleet } from './boats/fleet';
395	import { btCrowdSlots, btCrowdTarget, btCrowdLevel, btCrowdShown, btInExclusion } from './boats/crowd';
396	import { TYPES, CAR_COLORS, BIKE_COLORS, placePart, _e, _q, type VehicleType } from '../common/traffic';
397	import { deckY } from '../bridges/dragon/profile';
398	import { ttlRoadY } from '../bridges/tran-thi-ly/profile';
399	
400	/* ============================ Xe cộ & thuyền của khu phố quanh Cầu Rồng ============================ */
401	interface Path { axis: 'x' | 'z'; min: number; max: number; fixed: number; profile?: (x: number) => number; hidden?: boolean }
402	interface CityVehicle { path: Path; lane: number; dir: number; type: VehicleType; s: number; speed: number; color: number }
403	
404	export const PATHS: Record<'axis' | 'ttl' | 'bachDang' | 'tranHungDao', Path> = {
405	  axis: { axis: 'x', min: -1900, max: 1480, fixed: 0, profile: deckY },
406	  ttl: { axis: 'x', min: -1900, max: 1480, fixed: CONFIG.ttl.z, profile: ttlRoadY, hidden: false }, // 2 làn trong mỗi chiều của Cầu Trần Thị Lý
407	  bachDang: { axis: 'z', min: -2400, max: 2400, fixed: -299 },
408	  tranHungDao: { axis: 'z', min: -2200, max: 2400, fixed: 299 }
409	};
410	const vehicles: CityVehicle[] = [];
411	export let vBody: THREE.InstancedMesh, vCabin: THREE.InstancedMesh, vHead: THREE.InstancedMesh, vTail: THREE.InstancedMesh;
412	
413	export function buildTraffic() {
414	  const addLane = (path: Path, lane: number, dir: number, count: number, speed: number, mix: { bike: number; bus: number }) => {
415	    const range = path.max - path.min;
416	    for (let k = 0; k < count; k++) {
417	      const r = rand(); const type: VehicleType = r < mix.bike ? 'bike' : r < mix.bike + mix.bus ? 'bus' : 'car';
418	      vehicles.push({ path, lane, dir, type, s: path.min + (k + rand() * 0.5) * range / count, speed,
419	        color: type === 'bike' ? BIKE_COLORS[k % BIKE_COLORS.length] : type === 'bus' ? 0xe8b923 : CAR_COLORS[Math.floor(rand() * CAR_COLORS.length)] });
420	    }
421	  };
422	  const lanes = [4.875, 8.625, 12.375];
423	  for (const dir of [1, -1]) {
424	    addLane(PATHS.axis, lanes[0], dir, 26, 15, { bike: 0.05, bus: 0.08 });
425	    addLane(PATHS.axis, lanes[1], dir, 30, 12.5, { bike: 0.3, bus: 0.06 });
426	    addLane(PATHS.axis, lanes[2], dir, 44, 9.5, { bike: 0.85, bus: 0 });
427	    for (const [p, n] of [[PATHS.bachDang, 26], [PATHS.tranHungDao, 22]] as [Path, number][]) {
428	      addLane(p, 3.5, dir, n, 11, { bike: 0.3, bus: 0.05 }); addLane(p, 7.5, dir, n + 10, 8.5, { bike: 0.8, bus: 0 });
429	    }
430	    addLane(PATHS.ttl, 4.625, dir, 22, 13, { bike: 0.2, bus: 0.05 }); addLane(PATHS.ttl, 8.375, dir, 30, 9, { bike: 0.8, bus: 0 });
431	  }
432	  const n = vehicles.length, box = new THREE.BoxGeometry(1, 1, 1);
433	  vBody = new THREE.InstancedMesh(box, MAT.vehicle, n);
434	  vCabin = new THREE.InstancedMesh(box, MAT.glass, n);
435	  vHead = new THREE.InstancedMesh(box, MAT.headLamp, n);
436	  vTail = new THREE.InstancedMesh(box, MAT.tailLamp, n);
437	  const col = new THREE.Color();
438	  vehicles.forEach((v, i) => { col.setHex(v.color); vBody.setColorAt(i, col); });
439	  for (const mm of [vBody, vCabin, vHead, vTail]) { mm.frustumCulled = false; mm.instanceMatrix.setUsage(THREE.DynamicDrawUsage); scene.add(mm); }
440	  vBody.castShadow = true;
441	}
442	const HIDDEN_M = new THREE.Matrix4().makeScale(0, 0, 0);
443	const _p = new THREE.Vector3();
444	const hideAt = (i: number, lamps: boolean) => { vBody.setMatrixAt(i, HIDDEN_M); vCabin.setMatrixAt(i, HIDDEN_M); if (lamps) { vHead.setMatrixAt(i, HIDDEN_M); vTail.setMatrixAt(i, HIDDEN_M); } };
445	/* Không cấp phát mỗi khung (D-018). Đèn pha/hậu chỉ hiện khi đêm > 0,3 (applyNight đặt visible trước hàm này): khi ẩn không ghi ma trận đèn;
446	   vị trí xe (v.s) vẫn cộng dồn như cũ nên khung đèn hiện lại thì ma trận được ghi đúng chỗ ngay trong khung đó */
447	export function updateTraffic(dt: number) {
448	  const lamps = vHead.visible;
449	  for (let i = 0; i < vehicles.length; i++) {
450	    const v = vehicles[i], P = v.path, range = P.max - P.min, T = TYPES[v.type];
451	    if (P.hidden) { hideAt(i, lamps); continue; } // làn tắt bằng nút bật/tắt
452	    v.s += v.dir * v.speed * dt;
453	    if (v.s > P.max) v.s -= range; if (v.s < P.min) v.s += range;
454	    if ((P === PATHS.axis || P === PATHS.ttl) && vanished(i, weatherFx.clear)) { hideAt(i, lamps); continue; }   // đóng cầu (bão): dọn dần xe trên Cầu Rồng, Trần Thị Lý
455	    let yaw: number, pitch = 0;
456	    if (P.axis === 'x') {
457	      const y = P.profile(v.s), slope = (P.profile(v.s + 1) - P.profile(v.s - 1)) / 2;
458	      _p.set(v.s, y + 0.02, P.fixed + v.dir * v.lane); yaw = v.dir > 0 ? 0 : Math.PI; pitch = Math.atan(slope * v.dir);
459	    } else {
460	      _p.set(P.fixed - v.dir * v.lane, CONFIG.roadY + 0.03, v.s); yaw = v.dir > 0 ? -Math.PI / 2 : Math.PI / 2;
461	    }
462	    _q.setFromEuler(_e.set(0, yaw, pitch, 'YZX'));
463	    placePart(vBody, i, _p, _q, 0, 0.3 + T.h / 2, T.len, T.h, T.w);
464	    placePart(vCabin, i, _p, _q, T.co * T.len, 0.3 + T.h + T.ch / 2, T.cl, T.ch, T.cw);
465	    if (!lamps) continue;
466	    placePart(vHead, i, _p, _q, T.len / 2 + 0.04, 0.3 + T.h * 0.6, 0.1, 0.22, T.w * 0.8);
467	    placePart(vTail, i, _p, _q, -T.len / 2 - 0.04, 0.3 + T.h * 0.6, 0.1, 0.22, T.w * 0.8);
468	  }
469	  vBody.instanceMatrix.needsUpdate = vCabin.instanceMatrix.needsUpdate = true;
470	  if (lamps) vHead.instanceMatrix.needsUpdate = vTail.instanceMatrix.needsUpdate = true;
471	}
472	
473	/* Vùng cấm thuyền quanh công trường dìm đốt hầm (Hầm vượt sông Hàn, z ≈ −1700): chỉ có hiệu lực khi on */
474	export const boatKeepOut = { on: false, z0: -1760, z1: -1640 };
475	
476	/* Thuyền du lịch dọc sông Hàn — một đội tàu (fleet) chung ở layer 0 (có phản chiếu): 7 tàu chạy + chỗ cho 15 tàu tụ tập ban đêm (Task 4) */
477	export interface RiverBoat { x: number; z: number; dir: number; speed: number; len: number; type: BoatTypeId }
478	const boats: RiverBoat[] = [];
479	let fleet: BoatFleet;
480	export const RIVER_CROWD_FIRST = 7;   // instance 7.. dành cho tàu tụ tập
481	export function buildBoats() {
482	  const lanesX = [-48, -22, 22, 48];
483	  for (let i = 0; i < 7; i++) {
484	    // giữ đúng 2 lời gọi rand() mỗi tàu, đúng thứ tự (speed rồi len) — bất biến chuỗi seed; r đổi sang khoảng dài của kiểu
485	    const speed = 3 + rand() * 2, r = rand(), type: BoatTypeId = i % 2 ? 'B' : 'A', [lo, hi] = CONFIG.boats.types[type].len;
486	    boats.push({ x: lanesX[i % 4], z: -2200 + i * 650, dir: lanesX[i % 4] > 0 ? 1 : -1, speed, len: lo + r * (hi - lo), type });
487	  }
488	  fleet = btCreateFleet(RIVER_CROWD_FIRST + crowd.length, ['A', 'B', 'C'], scene, 'boats-river');
489	  boats.forEach((b, i) => btSetInfo(fleet, i, { type: b.type, variant: i % 3, led: (i * 2) % CONFIG.boats.led.colors.length, name: i % CONFIG.boats.names.length }));
490	  crowd.forEach((c, k) => btSetInfo(fleet, RIVER_CROWD_FIRST + k, c));
491	}
492	/* Tàu tụ tập ban đêm quanh Cầu Rồng / Cầu sông Hàn (spec G5, G6): đậu, trôi tròn chậm, mũi lắc nhẹ; hiện so le theo mức đêm, về bến khi bão */
493	const crowd = btCrowdSlots(), crowdA: number[] = crowd.map(() => 0);
494	let crowdLevel = 0;
495	export function btStepCrowd(f: BoatFleet, first: number, t: number, dt: number) {
496	  const C = CONFIG.boats.crowd, w = (Math.PI * 2) / C.driftPeriod;
497	  crowdLevel = btCrowdLevel(crowdLevel, btCrowdTarget(shared.uNight.value, weatherFx.boatAway), dt);
498	  crowd.forEach((c, k) => {
499	    const on = btCrowdShown(k, crowdLevel); crowdA[k] = on ? 1 : 0;
500	    if (!on) { btHideBoat(f, first + k); return; }
501	    const ph = t * w + c.phase, i = first + k;
502	    bq.setFromEuler(_e.set(Math.sin(t * 0.7 + k) * 0.012 * windFx.boatRock, c.yaw + C.yawSwing * Math.sin(ph * 0.7), Math.sin(t * 0.9 + k * 2) * 0.018 * windFx.boatRock, 'YXZ'));
503	    btSetBoat(f, i, bBase.set(c.x + C.drift * Math.cos(ph), 0, c.z + C.drift * Math.sin(ph)), bq, c.len);
504	  });
505	}
506	const bq = new THREE.Quaternion(), bBase = new THREE.Vector3();
507	export function updateBoats(dt: number, t: number) {
508	  boats.forEach((b, i) => {
509	    b.z += b.dir * b.speed * dt * (1 - weatherFx.boatAway); if (b.z > 2500) b.z = -2500; if (b.z < -2500) b.z = 2500;   // bão: thuyền chậm dần rồi dừng
510	    if (boatKeepOut.on && b.z > boatKeepOut.z0 && b.z < boatKeepOut.z1) b.z = b.dir > 0 ? boatKeepOut.z0 : boatKeepOut.z1;
511	    if (vanished(i, weatherFx.boatAway)) { btHideBoat(fleet, i); return; }   // về bến: ẩn dần
512	    bq.setFromEuler(_e.set(Math.sin(t * 0.9 + i) * 0.015 * windFx.boatRock, b.dir > 0 ? 0 : Math.PI, Math.sin(t * 1.1 + i * 2) * 0.02 * windFx.boatRock, 'YXZ'));   // mũi theo hướng chạy; tròng trành tăng theo gió (mặc định ×1)
513	    btSetBoat(fleet, i, bBase.set(b.x, 0, b.z), bq, b.len);
514	  });
515	  btStepCrowd(fleet, RIVER_CROWD_FIRST, t, dt);
516	  btCommit(fleet);
517	}
518	/* Cho test (__app.boats) */
519	export const boatsTest = { fleets: () => btFleets, running: () => boats, types: CONFIG.boats.types, crowd, crowdFirst: RIVER_CROWD_FIRST, crowdAlpha: () => crowdA, inExclusion: btInExclusion, drift: CONFIG.boats.crowd.drift };
