      T.body.setMatrixAt(i, HIDDEN_M); T.cabin.setMatrixAt(i, HIDDEN_M); if (lamps) { T.head.setMatrixAt(i, HIDDEN_M); T.tail.setMatrixAt(i, HIDDEN_M); }
