    this.planes = [
      new THREE.Plane(new THREE.Vector3(-1, 0, 0), PLANE_OFF), new THREE.Plane(new THREE.Vector3(1, 0, 0), -CUT_X),
      new THREE.Plane(new THREE.Vector3(0, 0, -1), CUT_Z - CUT_STRIP), new THREE.Plane(new THREE.Vector3(0, 0, 1), -CUT_Z)
    ];
    // tấm mặt cắt địa chất đặt sát mặt phía Nam, quay mặt về phía Bắc (nơi camera đứng)
    const tex = drawGeology(); M.textures.push(tex);
    this.plane = new THREE.Mesh(new THREE.PlaneGeometry(CUT_X * 2, Y_TOP - Y_BOT), new THREE.MeshBasicMaterial({ map: tex, transparent: true, alphaTest: 0.04, fog: false }));
    this.plane.rotation.y = Math.PI; this.plane.position.set(0, (Y_TOP + Y_BOT) / 2, CUT_Z + 0.04);
    this.plane.visible = false; this.plane.name = 'hr-geology'; this.plane.layers.set(1); scene.add(this.plane);
    this.patchWater();
    // vật liệu bị bóc: đất, đường, cây, đèn, nhà (vật liệu riêng của buildCity) và hầm
    const set = new Set<THREE.Material>([MAT.land, MAT.sand, MAT.paver, MAT.stone, MAT.grass, MAT.road, MAT.road2, MAT.trunk, MAT.leaf, MAT.palm, MAT.lampPole, MAT.bulb,
      MAT.vehicle, MAT.glass, MAT.headLamp, MAT.tailLamp, btFleetMaterial,
      M.concrete, M.bore, M.roadIn, M.roadOut, M.louver, M.brick, M.wave, M.bed, M.rubble, M.steel, M.lampThr, M.lampIn, M.lampCorr, M.fan, M.sos, M.extinguisher, M.door, M.exit, M.laneGreen, M.guide, M.equip, M.grate, M.basket]);
    scene.traverse((o) => { const i = o as THREE.InstancedMesh; if (i.isInstancedMesh && i.parent && (i.parent as THREE.LOD).isLOD) set.add(i.material as THREE.Material); });
    this.mats = [...set];
    for (const m of this.mats) { m.clippingPlanes = this.planes; m.clipIntersection = true; m.needsUpdate = true; }   // lúc dựng, trước lần biên dịch đầu
  }
  /* Nước: bỏ các điểm nằm trong máng hầm hở (nước trải vô hạn ở y = 0 sẽ lọt vào máng) và trong vùng bóc khi bật mặt cắt */
  private patchWater() {
    const mat = water.material as THREE.ShaderMaterial;
    mat.uniforms.uHoles = { value: HR_HOLES.map((h) => new THREE.Vector4(h.x0, h.z0, h.x1, h.z1)) };
    mat.uniforms.uCut = { value: new THREE.Vector4(-CUT_X, CUT_Z - CUT_STRIP, CUT_X, CUT_Z) };
    mat.uniforms.uCutOn = { value: 0 };
    mat.fragmentShader = mat.fragmentShader.replace('void main() {', `uniform vec4 uHoles[${HR_HOLES.length}]; uniform vec4 uCut; uniform float uCutOn;
      bool inRect(vec4 r, vec2 p) { return p.x > r.x && p.x < r.z && p.y > r.y && p.y < r.w; }
      void main() {
        vec2 wp = worldPosition.xz;
        for (int i = 0; i < ${HR_HOLES.length}; i++) if (inRect(uHoles[i], wp)) discard;
        if (uCutOn > 0.5 && inRect(uCut, wp)) discard;`);
    mat.needsUpdate = true;
  }
  setSection(on: boolean) {
    if (on === this.section) return;
    this.section = on; this.plane.visible = on;
    this.planes[0].constant = on ? -CUT_X : PLANE_OFF;
    (water.material as THREE.ShaderMaterial).uniforms.uCutOn.value = on ? 1 : 0;
    this.applyWater();
  }
  setGlass(on: boolean) { if (on === this.glass) return; this.glass = on; this.applyWater(); }
  private applyWater() {
    const clear = this.section || this.glass, mat = water.material as THREE.ShaderMaterial;
    mat.transparent = clear; mat.depthWrite = !clear; mat.uniforms.alpha.value = clear ? 0.4 : 1;
  }
}

import * as THREE from 'three';
import { shared } from '../../core/shared';
import { BridgeBase } from '../../common/BridgeBase';
import { createTraffic, stepTraffic, type Traffic } from '../../common/traffic';
import { boatKeepOut } from '../../environment/traffic';
import { HR, hrRoadY, hrInside } from './profile';
import { hrMaterials, hrUpdateLamps, type HrMaterials } from './materials';
import { buildBore, spinFans, type Bore } from './bore';
import { hrBuildOutdoor } from './outdoor';
import { hrBuildRiverbed, type Riverbed } from './riverbed';
import { hrClearCorridor } from './corridor';
import { Cutaway } from './cutaway';
import { ImmersionController, IM_STATES, type ImState } from './immersion';

/* ======================================================================
   HẦM VƯỢT SÔNG HÀN — phương án đề xuất 2025 (chưa xây), nối Đống Đa (Hải Châu) với Vân Đồn (Sơn Trà)
   Group đặt tại z = −1700; tim sông là x = 0. Hầm dìm 5 đốt × 120 m qua sông, hầm kín trên bờ, hầm hở hai đầu.
   ====================================================================== */
export class HanTunnel extends BridgeBase<HrMaterials> {
  underground = new THREE.Group();    // vỏ + nội thất hầm kín: chỉ hiện khi camera ở trong hầm, bật mặt cắt hoặc đang mô phỏng dìm
  bores!: { west: Bore; mid: Bore; east: Bore };
  riverbed!: Riverbed;
  cutaway!: Cutaway;
  readonly cfg = HR;
  ctrl = new ImmersionController();
  traffic!: Traffic;
  sim = new THREE.Group();
  private masts: THREE.Mesh[] = [];
  private tugs: THREE.Group[] = [];
  private bulk: THREE.Mesh[] = [];
  private fanAngle = 0;
  forceInterior = false;               // Tour/UI muốn thấy nội thất bất kể vị trí camera

  constructor() {
    super('HanTunnel', 'hr', HR.z, new THREE.Vector3(0, 5, HR.z), HR.lodDistance);
    this.mats = hrMaterials();
    this.farDistance = HR.farDistance;
    this.closable = false;           // bão: hầm vẫn lưu thông (bơm thoát nước làm việc), không theo lệnh đóng cầu
    hrClearCorridor();               // phải chạy trước khi dựng cọ và đèn của chính hầm
    // vỏ + nội thất theo ba đoạn: đốt 3 (±60 m) tách riêng để mô phỏng dìm
    const M = this.mats;
    this.bores = { west: buildBore(-HR.coverHalf, -60, M, 'hr-bore-w'), mid: buildBore(-60, 60, M, 'hr-bore-mid'), east: buildBore(60, HR.coverHalf, M, 'hr-bore-e') };
    this.underground.name = 'hr-underground';
    this.underground.add(this.bores.west.group, this.bores.mid.group, this.bores.east.group);
    this.underground.traverse((o) => { if ((o as THREE.Mesh).isMesh) (o as THREE.Mesh).receiveShadow = true; });
    this.group.add(this.underground); this.noReflect.push(this.underground);
    this.riverbed = hrBuildRiverbed(M);
    this.group.add(this.riverbed.group); this.noReflect.push(this.riverbed.group);
    hrBuildOutdoor(this);
    this.buildSim();
    this.traffic = createTraffic(this, { seed: 3100, x0: -1500, x1: 1480, busColor: 0xe0a21b, lanes: [
      { off: HR.laneOffsets[0], n: 34, speed: HR.carSpeed, bike: 0.03, bus: 0.12 },
      { off: HR.laneOffsets[1], n: 30, speed: HR.carSpeed, bike: 0.06, bus: 0.12 },
      { off: HR.laneOffsets[2], n: 110, speed: HR.bikeSpeed, bike: 0.94, bus: 0 }   // làn phải: xe máy
    ] });
    this.finalize();
    // tiết kiệm draw call: bê tông/thép gộp không vào lượt phản chiếu mặt nước; thép và cột đèn không đổ bóng
    for (const o of this.group.children) { const me = o as THREE.Mesh; if (me.isMesh && (me.name === 'hr-concrete' || me.material === this.mats.steel)) { me.layers.set(1); if (me.material === this.mats.steel) me.castShadow = false; } }
    this.details.traverse((o) => { (o as THREE.Mesh).castShadow = false; });
    this.cutaway = new Cutaway(this.mats);
    this.ctrl.addEventListener('immerseStart', () => { this.cutaway.setGlass(true); boatKeepOut.on = true; });
    this.ctrl.addEventListener('immerseDone', () => { this.cutaway.setGlass(false); boatKeepOut.on = false; });
    this.applySim();
  }
  /* Phần chỉ có khi mô phỏng dìm: vách ngăn kín hai đầu đốt, tháp định vị, tàu kéo, phao đánh dấu hào */
  private buildSim() {
    const M = this.mats, sim = this.sim;
    sim.name = 'hr-sim'; sim.visible = false;
    for (const s of [-1, 1]) {
      const b = new THREE.Mesh(new THREE.BoxGeometry(0.7, HR.roofTop + HR.slabBelow, HR.halfWidth * 2), M.bulk);
      b.position.set(s * (60 - 0.35), hrRoadY(s * 60) + (HR.roofTop - HR.slabBelow) / 2, 0); b.visible = false; b.castShadow = true;
      this.bores.mid.group.add(b); this.bulk.push(b);
      const mast = new THREE.Mesh(new THREE.BoxGeometry(1.2, 1, 1.2), M.pontoon); mast.castShadow = true; sim.add(mast); this.masts.push(mast);
      const tug = new THREE.Group();
      const hull = new THREE.Mesh(new THREE.BoxGeometry(5.5, 2.4, 14), M.tug), cab = new THREE.Mesh(new THREE.BoxGeometry(3.4, 2.4, 5), M.pontoon);
      hull.position.y = 0.6; cab.position.set(0, 2.6, -2); hull.castShadow = cab.castShadow = true; tug.add(hull, cab); sim.add(tug); this.tugs.push(tug);
    }
    const buoy = new THREE.InstancedMesh(new THREE.SphereGeometry(0.9, 10, 8), M.buoy, 4), m = new THREE.Matrix4();
    [[-70, -47], [70, -47], [-70, 47], [70, 47]].forEach(([x, z], i) => buoy.setMatrixAt(i, m.makeTranslation(x, 0.2, z)));
    sim.add(buoy);
    this.group.add(sim); this.noReflect.push(sim);
  }
  /* Tư thế đốt 3 và các phụ kiện theo trạng thái mô phỏng */
  private applySim() {
    const c = this.ctrl, busy = c.busy, mid = this.bores.mid, rb = this.riverbed.ribbons[2], t = performance.now() / 1000;
    // Đốt nổi dập dềnh theo sóng: chỉ chìm xuống (−0,08…0 m), không bao giờ cao hơn FLOAT_LIFT (mạn khô +0,8 m), kể cả khung đầu của BALLAST
    mid.group.position.set(c.gap, c.lift + (busy && c.lift > 1 ? (Math.sin(t * 1.3) - 1) * 0.04 : 0), c.zOff);
    mid.fit.visible = !busy || c.state === 'DONE';
    this.sim.visible = busy && c.state !== 'DONE';
    this.bulk.forEach((b) => { b.visible = busy && c.state !== 'BACKFILL' && c.state !== 'DONE'; });
    rb.visible = !busy || c.fill > 0.01; rb.scale.z = busy ? Math.max(c.fill, 0.001) : 1;
    const top = hrRoadY(0) + HR.roofTop + c.lift;
    this.masts.forEach((m, i) => {
      const s = i ? 1 : -1, h = Math.max(1, 6 - top);
      m.position.set(c.gap + s * 45, top + h / 2, c.zOff); m.scale.set(1, h, 1); m.visible = c.state !== 'BACKFILL';
    });
    this.tugs.forEach((g, i) => {
      const s = i ? 1 : -1;
      g.position.set(s * 78 + c.gap, 0.4 + Math.sin(t * 1.1 + i) * 0.06, c.zOff - 22 - c.tugs * 160);
      g.rotation.z = Math.sin(t * 0.9 + i * 2) * 0.012;
    });
  }
  setForceInterior(on: boolean) { this.forceInterior = on; }
  /* Thuyền đang chạy ngang vùng thi công thì giữ lại ở mép vùng cấm (dùng cho thuyền của các cầu khác) */
  holdBoats(list: { z: number; dir: number }[]) {
    if (!this.ctrl.busy) return;
    for (const b of list) if (b.z > boatKeepOut.z0 && b.z < boatKeepOut.z1) b.z = b.dir > 0 ? boatKeepOut.z0 : boatKeepOut.z1;
  }
  update(dt: number, elapsed: number, cam: THREE.Camera) {
    this.updateLod(cam); const c = this.ctrl, dist = cam.position.distanceTo(this.center);
    this.group.visible = dist < HR.hideDistance;   // xa quá thì không vẽ gì (bê tông, thép gộp không có LOD riêng)
    c.update(dt);
    hrUpdateLamps(this.mats, shared.uNight.value);
    const p = cam.position, inside = hrInside(p.x, p.y, p.z - 0);
    this.underground.visible = this.details.visible && (inside || this.cutaway.section || c.busy || this.forceInterior);
    if (this.underground.visible) {
      this.fanAngle += dt * 14;
      for (const b of Object.values(this.bores)) spinFans(b, this.fanAngle);
    }
    this.applySim();
    // Đáy sông là một phần của chế độ mặt cắt / nước trong / mô phỏng: KHÔNG phụ thuộc LOD chi tiết (lodDistance 600 m nhỏ hơn khoảng cách góc hrOverview ≈ 800 m).
    // Xa hơn hideDistance thì cả group đã ẩn. Chế độ tắt thì vẫn ẩn → góc nhìn thường không thêm draw call
    this.riverbed.group.visible = this.cutaway.section || this.cutaway.glass || c.busy;
    this.life.visible = this.life.visible && !c.busy && dist < HR.lifeDistance;     // đóng đường khi thi công; xe chỉ vẽ khi camera gần
    if (this.life.visible) stepTraffic(this.traffic, dt, hrRoadY, false);   // hầm vẫn lưu thông khi bão (phương án đề xuất)
  }
  get state(): ImState { return this.ctrl.state; }
  static readonly states = IM_STATES;
}

import * as THREE from 'three';
import { CONFIG } from '../../config';
import { rng, lerp } from '../../common/math';
import { createTraffic, stepTraffic, type Traffic, type BridgeVehicle } from '../../common/traffic';
import { createBoats } from '../../common/boats';
import { btCreateFleet, btSetInfo, btSetBoat, btCommit } from '../../environment/boats/fleet';
import { createPeople, type Walker } from '../../common/people';
import { SH, shRoadY } from './profile';
import type { SwingController } from './SwingController';
import type { SongHanBridge } from './SongHanBridge';

/* [life] xe dừng trước barie, người đi bộ, thuyền du lịch, tàu buồm cao chờ mở luồng */
export function shBuildLife(bridge: SongHanBridge) {
  bridge.traffic = createTraffic(bridge, { seed: 2000, x0: -1500, x1: 1480, busColor: 0x2f7fc1,
    lanes: [{ off: SH.lane, n: 26, speed: 11, bike: 0.6, bus: 0.04 }] });
  // thuyền du lịch nối lộ trình Cầu Rồng – Cầu sông Hàn – Cầu Thuận Phước (giữa các làn thuyền chung)
  bridge.boats = createBoats(bridge, [
    { x: 31, z: 700, dir: -1, speed: 3.4, len: 22, w: 7, h: 2.6, cab: 2.9, type: 'A' },
    { x: 41, z: -900, dir: 1, speed: 3.0, len: 18, w: 6.5, h: 2.5, cab: 2.7, type: 'B' }
  ], 'sh-boats');
  // người đi bộ: lề cầu (phần cố định) và lề ven sông Bạch Đằng
  const rnd = rng(2903), list: Walker[] = [], zs = SH.hw - SH.sidewalk / 2 - 0.15;
  for (let i = 0; i < 36; i++) {
    const west = i % 2 === 0, lo = west ? -285 : SH.fixedStart + 8, hi = west ? -SH.fixedStart - 8 : 285;
    list.push({ x: lerp(lo, hi, rnd()), z: (rnd() < 0.5 ? -1 : 1) * zs, lo, hi, dir: rnd() < 0.5 ? -1 : 1, speed: 1 + rnd() * 0.5, profile: (x) => shRoadY(x) + 0.25 });
  }
  for (let i = 0; i < 40; i++) list.push({ x: -276 + (rnd() - 0.5) * 18, z: lerp(-420, 420, rnd()), lo: -420, hi: 420, dir: rnd() < 0.5 ? -1 : 1,
    speed: 0.9 + rnd() * 0.5, axis: 'z', profile: () => CONFIG.landY + 0.05 });
  bridge.people = createPeople(bridge, list, bridge.mats.person, 'sh-people', rnd);
  // tàu buồm cao: cột buồm cao hơn tĩnh không, chỉ qua được khi cầu mở (luồng phía Tây)
  const ship = new THREE.Group(); ship.name = 'sh-tall-ship';
  // một đội tàu 1 chiếc kiểu E (thân, nhà boong, cột, buồm gộp) = 1 lệnh vẽ; group ship vẫn do SongHanBridge di chuyển
  const tall = btCreateFleet(1, ['E'], ship, 'sh-tall-ship-boat');
  btSetInfo(tall, 0, { type: 'E', variant: 0, led: 4, name: 0 });
  btSetBoat(tall, 0, new THREE.Vector3(), new THREE.Quaternion(), 30); btCommit(tall);
  ship.position.set(-36, 0, -260);
  bridge.life.add(ship);
  bridge.ship = { obj: ship, z: -260, target: -260, dir: 1, speed: 4.5 };
}

/* Xe: như hệ chung, nhưng khi không cho vào nhịp quay thì xếp hàng trước barie */
const before: BridgeVehicle[] = [];          // mảng tạm dùng lại (D-018)
let saved = new Float64Array(0);           // tốc độ gốc (double: trả lại đúng từng bit)
const byDist = (a: BridgeVehicle, b: BridgeVehicle) => Math.abs(a.s) - Math.abs(b.s);
export function shStepTraffic(T: Traffic, dt: number, ctrl: SwingController) {
  const bx = SH.barrierX;
  if (!ctrl.allowEntry) {
    for (const dir of [1, -1]) {
      before.length = 0;
      for (const v of T.list) if (v.dir === dir && (dir > 0 ? v.s < -bx : v.s > bx)) before.push(v);
      before.sort(byDist);
      before.forEach((v, r) => { v.hold = bx + 3 + r * 7.5; });
    }
  }
  if (saved.length !== T.list.length) saved = new Float64Array(T.list.length);
  for (let i = 0; i < T.list.length; i++) saved[i] = T.list[i].speed;
  T.list.forEach((v) => {
    if (ctrl.allowEntry || v.hold === undefined) return;
    const stopAt = -v.dir * v.hold, dist = (stopAt - v.s) * v.dir;          // khoảng còn lại tới vị trí dừng
    if (dist <= 0 || (v.dir > 0 ? v.s >= -bx : v.s <= bx)) return;          // đã qua barie thì chạy tiếp
    v.speed = Math.min(v.speed, Math.max(0, dist / Math.max(dt, 1e-3)));
  });
  stepTraffic(T, dt, shRoadY);
  T.list.forEach((v, i) => { v.speed = saved[i]; if (ctrl.allowEntry) delete v.hold; });
}

import { createTraffic } from '../../common/traffic';
import { createBoats } from '../../common/boats';
import { TP } from './profile';
import type { ThuanPhuocBridge } from './ThuanPhuocBridge';

/* [life] xe cộ & tàu thuyền (hệ dùng chung trong common/) */
export function tpBuildTraffic(bridge: ThuanPhuocBridge) {
